                    // the rest at once, then the newlines translated
                    do { sb.Append(_chars, _cpos, _clen - _cpos); _cpos = _clen; } while (Fill());
                    string all = sb.ToString();
                    return universal && all.Contains('\r') ? all.Replace("\r\n", "\n").Replace('\r', '\n') : all;
                }
                while (sb.Length < size)
                {
                    int c = NextChar();
                    if (c < 0) break;
                    if (c == '\r' && universal)
                    {
                        if (PeekChar() == '\n') _cpos++;
                        sb.Append('\n');
                    }
                    else sb.Append((char)c);
                }
                return sb.ToString();
            }

            public override string readline(long size = -1)
            {
                PrepareRead();
                if (size < 0 && _newline != "\r" && _newline != "\r\n" && _cpos < _clen)
                {
                    // the common case: a whole line ending in \n (no \r) among the characters decoded already
                    var span = _chars.AsSpan(_cpos, _clen - _cpos);
                    int k = span.IndexOfAny('\r', '\n');
                    if (k >= 0 && span[k] == '\n')
                    {
                        var line = new string(_chars, _cpos, k + 1);
                        _cpos += k + 1;
                        return line;
                    }
                }
                var sb = new StringBuilder();
                while (size < 0 || sb.Length < size)
                {
                    int c = NextChar();
                    if (c < 0) break;
                    if (c == '\r' && (_newline == null || _newline == "" || _newline == "\r" || _newline == "\r\n"))
                    {
                        if (_newline == "\r") { sb.Append('\r'); break; }
                        bool crlf = PeekChar() == '\n';
                        if (_newline == "\r\n" && !crlf) { sb.Append('\r'); continue; }
                        if (crlf) _cpos++;
                        sb.Append(_newline == null ? "\n" : crlf ? "\r\n" : "\r");
                        break;
                    }
                    sb.Append((char)c);
                    if (c == '\n' && _newline != "\r" && _newline != "\r\n") break;
                }
                return sb.ToString();
            }

            public override long write(string s)
            {
                var st = S;
                if (!st.CanWrite) throw Unsupported("not writable");
                DropReadAhead();
                string text = _newline == null ? (Environment.NewLine == "\n" ? s : s.Replace("\n", Environment.NewLine))
                            : _newline is "" or "\n" ? s : s.Replace("\n", _newline);
                if (_bom && _atStart && (!st.CanSeek || st.Position == 0)) st.Write(_enc.GetPreamble().Length > 0 ? _enc.GetPreamble() : new UTF8Encoding(true).GetPreamble());
                _atStart = false;
                st.Write(_enc.GetBytes(text));
                if (_writeThrough || (_lineBuffering && (s.Contains('\n') || s.Contains('\r')))) st.Flush();
                return s.Length;
            }

            /// <summary>Gives back characters decoded ahead of the reader, so the stream position is the text position (before writing or seeking).</summary>
            void DropReadAhead()
            {
                if (_clen - _cpos == 0 && _carry.Length == 0) return;
                var s = S;
                if (s.CanSeek) s.Position = tell();
                _cpos = _clen = 0; _carry = Array.Empty<byte>(); _dec.Reset(); _eof = false;
            }

            public override void flush() { _checkClosed(); if (_s != null && _s.CanWrite) _s.Flush(); }

            /// <summary>The byte offset of the next character (an opaque cookie in CPython; a plain offset when no decoder state is pending).</summary>
            public override long tell()
            {
                var s = S;
                if (!s.CanSeek) throw Unsupported("underlying stream is not seekable");
                if (s.CanWrite) s.Flush();
                return s.Position - _carry.Length - _enc.GetByteCount(_chars, _cpos, _clen - _cpos);
            }

            public override long seek(long offset, long whence = 0)
            {
                var s = S;
                if (!s.CanSeek) throw Unsupported("underlying stream is not seekable");
                if (whence == 1 && offset != 0) throw Unsupported("can't do nonzero cur-relative seeks");
                if (whence == 2 && offset != 0) throw Unsupported("can't do nonzero end-relative seeks");
                if (whence == 0 && offset < 0) throw new ArgumentException($"negative seek position {offset}");
                if (s.CanWrite) s.Flush();
                long target = whence == 0 ? offset : whence == 1 ? tell() : s.Length;
                s.Position = target;
                _cpos = _clen = 0; _carry = Array.Empty<byte>(); _dec.Reset(); _eof = false;
                _atStart = target == 0;
                return target;
            }

            public override dynamic? truncate(long? size = null)
            {
                var s = S;
                long n = size ?? tell();
                s.Flush();
                s.SetLength(n);
                return n;
            }

            public override object? detach()
            {
                flush();
                var b = buffer;
                _s = null;
                buffer = null;
                return b;
            }

            /// <summary>Changes the encoding, errors or newline handling of a stream (only before reading).</summary>
            public void reconfigure(string? encoding = null, string? errors = null, string? newline = "￿", bool? line_buffering = null, bool? write_through = null)
            {
                if (encoding == null && errors == null && newline == "￿") return;
                flush();
                Init(_s!, encoding ?? _encoding, errors ?? (encoding != null ? "strict" : _errors), newline == "￿" ? _newline : newline);
            }

            public override void close()
            {
                if (closed || _s == null) { base.close(); return; }
                try { if (_s.CanWrite) _s.Flush(); } catch (ObjectDisposedException) { }
                base.close();
                if (buffer is IOBase b) b.close(); else _s.Dispose();
            }

            public override bool closed => _s == null ? base.closed : buffer is IOBase b ? b.closed : base.closed;
            public override string ToString()
            {
                object? displayName = _name ?? Builtins.getattr((object?)buffer, "name", null);
                string named = displayName != null ? $" name={Builtins.repr(displayName)}" : "";
                string modeText = _mode != null ? $" mode='{_mode}'" : "";
                return $"<_io.TextIOWrapper{named}{modeText} encoding='{_encoding}'>";
            }
        }

        /// <summary>io.StringIO: an in-memory text stream (the implementation is Typhon.Runtime.StringIO).</summary>
        internal class StringIO : Typhon.Runtime.StringIO
        {
            // (separate overloads rather than defaults: a Python subclass inherits each, so MyIO() and MyIO("text") both work)
            public StringIO() : base("", "\n") { }
            public StringIO(string? initial_value) : base(initial_value ?? "", "\n") { }
            public StringIO(string? initial_value, string? newline) : base(initial_value ?? "", newline) { }
        }
    }
}

namespace Typhon.Runtime
{
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using System.Text;
    using Typhon.Stdlib;

    /// <summary>Byte-stream operations shared by the binary file objects (BytesIO, FileIO, Buffered*, open(..., 'rb')).</summary>
    internal static class StreamOps
    {
        public static System.IO.SeekOrigin Origin(long whence) => whence switch
        {
            0 => System.IO.SeekOrigin.Begin,
            1 => System.IO.SeekOrigin.Current,
            2 => System.IO.SeekOrigin.End,
            _ => throw new ArgumentException($"invalid whence ({whence}, should be 0, 1 or 2)"),
        };

        /// <summary>read(size): up to size bytes (all that is left when negative); once: a single read of the stream (read1).</summary>
        public static PyBytes Read(System.IO.Stream s, long size, bool once = false)
        {
            if (!s.CanRead) throw io.Unsupported("read");
            if (size < 0)
            {
                var ms = new System.IO.MemoryStream();
                s.CopyTo(ms);
                return new PyBytes(ms.ToArray());
            }
            var buf = new byte[size];
            int got = 0, n;
            while (got < size && (n = s.Read(buf, got, (int)size - got)) > 0) { got += n; if (once) break; }
            return new PyBytes(got == size ? buf : buf.AsSpan(0, got).ToArray());
        }

        public static long ReadInto(System.IO.Stream s, PyByteArray b)
        {
            var data = Read(s, b.Count);
            for (int i = 0; i < data.Count; i++) b[i] = data.Data[i];
            return data.Count;
        }

        public static PyBytes ReadLine(System.IO.Stream s, long size)
        {
            if (!s.CanRead) throw io.Unsupported("read");
            var ms = new System.IO.MemoryStream();
            int b;
            while ((size < 0 || ms.Length < size) && (b = s.ReadByte()) >= 0) { ms.WriteByte((byte)b); if (b == '\n') break; }
            return new PyBytes(ms.ToArray());
        }

        /// <summary>readline() of a binary object without a .NET stream (a Python subclass): byte by byte through read(1).</summary>
        public static PyBytes ReadLine(io.IOBase f, long size)
        {
            var ms = new System.IO.MemoryStream();
            while (size < 0 || ms.Length < size)
            {
                PyBytes one = f is io.RawIOBase r ? r.read(1) : ((io.BufferedIOBase)f).read(1);
                if (one.Count == 0) break;
                ms.WriteByte(one.Data[0]);
                if (one.Data[0] == '\n') break;
            }
            return new PyBytes(ms.ToArray());
        }

        public static List<PyBytes> ReadLines(IEnumerable<PyBytes> f, long hint)
        {
            var lines = new List<PyBytes>();
            long total = 0;
            foreach (var l in f)
            {
                lines.Add(l);
                total += l.Count;
                if (hint > 0 && total >= hint) break;
            }
            return lines;
        }

        public static long Write(System.IO.Stream s, byte[] data)
        {
            if (!s.CanWrite) throw io.Unsupported("write");
            s.Write(data);
            return data.Length;
        }

        /// <summary>FileIO's mode as CPython shows it ('rb', 'wb', 'rb+', ...).</summary>
        public static string RawMode(string mode)
        {
            bool plus = mode.Contains('+');
            char kind = mode.Contains('w') ? 'w' : mode.Contains('a') ? 'a' : mode.Contains('x') ? 'x' : 'r';
            return kind == 'r' ? (plus ? "rb+" : "rb") : kind == 'a' ? (plus ? "ab+" : "ab") : kind + (plus ? "b+" : "b");
        }

        internal static long OpenFlags(string mode)
        {
            long access = mode.Contains('+') ? os_.O_RDWR : mode.Contains('r') ? os_.O_RDONLY : os_.O_WRONLY;
            long flags = mode.Contains('w') ? os_.O_CREAT | os_.O_TRUNC :
                mode.Contains('x') ? os_.O_CREAT | os_.O_EXCL : mode.Contains('a') ? os_.O_CREAT | os_.O_APPEND : 0;
            return access | flags | os_.O_BINARY;
        }

        /// <summary>Opens a file with Python's mode letters (r, w, a, x, +), raising CPython's errors.</summary>
        public static System.IO.FileStream OpenFile(string path, string mode)
        {
            var fm = mode.Contains('w') ? System.IO.FileMode.Create : mode.Contains('a') ? System.IO.FileMode.Append : mode.Contains('x') ? System.IO.FileMode.CreateNew : System.IO.FileMode.Open;
            bool plus = mode.Contains('+');
            var fa = fm == System.IO.FileMode.Open && !plus ? System.IO.FileAccess.Read
                   : plus ? System.IO.FileAccess.ReadWrite : System.IO.FileAccess.Write;
            if (fm == System.IO.FileMode.Append && plus) fm = System.IO.FileMode.OpenOrCreate; // a+: read anywhere, write at the end
            try
            {
                var s = new System.IO.FileStream(path, fm, fa, System.IO.FileShare.ReadWrite);
                if (mode.Contains('a') && plus) s.Seek(0, System.IO.SeekOrigin.End);
                return s;
            }
            catch (Exception e) when (e is System.IO.IOException || e is UnauthorizedAccessException)
            {
                throw OsErrors.FromOpen(e, path, fm == System.IO.FileMode.CreateNew);
            }
        }

        /// <summary>The .NET stream behind a binary file object, or an adapter that calls its Python methods (read/readinto/write/seek).</summary>
        public static System.IO.Stream StreamOf(object raw) => raw switch
        {
            System.IO.Stream s => s,
            io.IOBase b when b.__stream is System.IO.Stream s => s,
            _ => new PyObjectStream(raw),
        };
    }

    /// <summary>A .NET stream over a Python file-like object (a RawIOBase/BufferedIOBase subclass, or anything with read/write).</summary>
    internal sealed class PyObjectStream : System.IO.Stream
    {
        readonly object _o;
        public PyObjectStream(object o) { _o = o; }
        dynamic D => _o;
        bool Has(string name) => Builtins.hasattr(_o, name);
        public override bool CanRead => _o is io.IOBase b ? b.readable() : Has("read") || Has("readinto");
        public override bool CanWrite => _o is io.IOBase b ? b.writable() : Has("write");
        public override bool CanSeek => _o is io.IOBase b ? b.seekable() : Has("seek");
        public override long Length { get { long pos = Position; long end = Seek(0, System.IO.SeekOrigin.End); Position = pos; return end; } }
        public override long Position { get => (long)D.tell(); set => D.seek(value, 0L); }
        public override void Flush() { if (Has("flush")) D.flush(); }
        public override int Read(byte[] buffer, int offset, int count)
        {
            if (_o is io.RawIOBase raw)
            {
                var ba = new PyByteArray(new byte[count]);
                long n = raw.readinto(ba);
                var got = ba.ToArray();
                Array.Copy(got, 0, buffer, offset, n);
                return (int)n;
            }
            object? data = _o is io.BufferedIOBase bb ? bb.read1(count) : D.read((long)count);
            var bytes = ByteOps.From(data);
            Array.Copy(bytes, 0, buffer, offset, bytes.Length);
            return bytes.Length;
        }
        public override void Write(byte[] buffer, int offset, int count)
        {
            var data = new PyBytes(buffer.AsSpan(offset, count).ToArray());
            if (_o is io.RawIOBase raw) { int done = 0; while (done < count) { long n = raw.write(new PyBytes(buffer.AsSpan(offset + done, count - done).ToArray())); if (n <= 0) break; done += (int)n; } }
            else if (_o is io.BufferedIOBase bb) bb.write(data);
            else D.write(data);
        }
        public override long Seek(long offset, System.IO.SeekOrigin origin) => (long)D.seek(offset, (long)(int)origin);
        public override void SetLength(long value) => D.truncate(value);
    }
}
